package com.bank.diag.repository;

import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Repository;
import java.util.List;
import java.util.Map;

@Repository
public class DiagnosticRepository {
    private final JdbcTemplate jdbc;

    public DiagnosticRepository(JdbcTemplate jdbc) { this.jdbc = jdbc; }

    // Are statistics stale? Compare live tuples to last analyze time.
    public boolean statsLookStale() {
        List<Map<String, Object>> rows = jdbc.queryForList(
            "SELECT last_analyze, last_autoanalyze, n_live_tup " +
            "FROM pg_stat_user_tables WHERE relname = 'transactions'");
        if (rows.isEmpty()) return false;
        Map<String, Object> r = rows.get(0);
        return r.get("last_analyze") == null && r.get("last_autoanalyze") == null;
    }

    // Is this query currently blocked on a lock?
    public int countLockWaiters() {
        Integer n = jdbc.queryForObject(
            "SELECT count(*) FROM pg_stat_activity WHERE wait_event_type = 'Lock'",
            Integer.class);
        return n == null ? 0 : n;
    }

    public void refreshStatistics() {
        jdbc.execute("ANALYZE transactions");
    }
}
