package com.bank.diag.service;

import com.bank.diag.model.Diagnosis;
import com.bank.diag.repository.DiagnosticRepository;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.stereotype.Service;

@Service
public class RegressionDiagnosticService {
    private static final Logger log = LoggerFactory.getLogger(RegressionDiagnosticService.class);
    private final DiagnosticRepository repo;

    public RegressionDiagnosticService(DiagnosticRepository repo) { this.repo = repo; }

    // Diagnose WHAT CHANGED before reaching for an index.
    public Diagnosis diagnose() {
        int lockWaiters = repo.countLockWaiters();
        if (lockWaiters > 0) {
            log.warn("Query is waiting on a lock — {} blocked sessions. Index will NOT help.", lockWaiters);
            return new Diagnosis(
                "Lock contention: a long transaction holds the table lock",
                "Find the blocker in pg_stat_activity and end that transaction; add statement_timeout",
                false);
        }
        if (repo.statsLookStale()) {
            log.warn("Statistics are stale after bulk load — planner picked a bad plan.");
            repo.refreshStatistics();
            return new Diagnosis(
                "Stale statistics after overnight bulk import of PENDING rows",
                "Run ANALYZE (done). Planner now estimates correctly. No new index needed.",
                false);
        }
        log.info("No lock wait and statistics are fresh — investigate parameter skew and data growth.");
        return new Diagnosis(
            "Likely parameter skew (PENDING now matches millions of rows)",
            "Review plan for this parameter; consider targeted index only if selectivity truly changed",
            false);
    }
}
